mapper.select:
SELECT
    (
        SELECT COUNT(*)
        FROM draw_record draw_row
        WHERE draw_row.draw_time >= #{startTime}
          AND draw_row.draw_time < #{endTime}

              AND draw_row.activity_id = #{activityId}

    ) AS draw_count,
    (
        SELECT COUNT(DISTINCT draw_row.user_id)
        FROM draw_record draw_row
        WHERE draw_row.draw_time >= #{startTime}
          AND draw_row.draw_time < #{endTime}

              AND draw_row.activity_id = #{activityId}

    ) AS participant_count,
    (
        SELECT COUNT(*)
        FROM winning_record winning_row
        INNER JOIN draw_record draw_row ON draw_row.id = winning_row.draw_record_id
        WHERE draw_row.draw_time >= #{startTime}
          AND draw_row.draw_time < #{endTime}

              AND draw_row.activity_id = #{activityId}

    ) AS win_count,
    (
        SELECT COALESCE(-SUM(point_row.change_amount), 0)
        FROM point_transaction point_row
        INNER JOIN draw_record draw_row
            ON draw_row.id = point_row.biz_id
           AND draw_row.user_id = point_row.user_id
        WHERE point_row.biz_type = 'DRAW'
          AND point_row.change_amount < 0
          AND draw_row.draw_time >= #{startTime}
          AND draw_row.draw_time < #{endTime}

              AND draw_row.activity_id = #{activityId}

    ) AS points_consumed,
    (
        SELECT COUNT(*)
        FROM winning_record winning_row
        INNER JOIN draw_record draw_row ON draw_row.id = winning_row.draw_record_id
        INNER JOIN activity_prize activity_prize_row
            ON activity_prize_row.id = winning_row.activity_prize_id
        WHERE activity_prize_row.prize_type_snapshot = 1
          AND draw_row.draw_time >= #{startTime}
          AND draw_row.draw_time < #{endTime}

              AND draw_row.activity_id = #{activityId}

    ) AS physical_win_count,
    (
        SELECT COUNT(DISTINCT winning_row.id)
        FROM winning_record winning_row
        INNER JOIN draw_record draw_row ON draw_row.id = winning_row.draw_record_id
        INNER JOIN activity_prize activity_prize_row
            ON activity_prize_row.id = winning_row.activity_prize_id
        INNER JOIN fulfillment_order fulfillment_row
            ON fulfillment_row.winning_record_id = winning_row.id
           AND fulfillment_row.status IN (1, 2, 3, 4)
        WHERE activity_prize_row.prize_type_snapshot = 1
          AND draw_row.draw_time >= #{startTime}
          AND draw_row.draw_time < #{endTime}

              AND draw_row.activity_id = #{activityId}

    ) AS claimed_physical_win_count

SELECT activity_prize_row.prize_type_snapshot AS prize_type, COUNT(*) AS win_count FROM winning_record winning_row INNER JOIN draw_record draw_row ON draw_row.id = winning_row.draw_record_id INNER JOIN activity_prize activity_prize_row ON activity_prize_row.id = winning_row.activity_prize_id WHERE draw_row.draw_time >= #{startTime} AND draw_row.draw_time < #{endTime} AND activity_prize_row.prize_type_snapshot IS NOT NULL
AND draw_row.activity_id = #{activityId}
GROUP BY activity_prize_row.prize_type_snapshot ORDER BY activity_prize_row.prize_type_snapshot
